window.EXAM_CHAPTER_DATA["west_econ"]["14_开放条件下的宏观经济"] = {"id":"14_开放条件下的宏观经济","name":"开放条件下的宏观经济","kps":[{"id":"KP01","name":"汇率与国际收支","file":"教材笔记/06_西方经济学/14_开放条件下的宏观经济/知识点/KP01_汇率与国际收支.md","questions":[{"id":"west_econ_14_开放条件下的宏观经济_KP01_1","num":"1","stem":"直接标价法是指：","options":{"A":"1单位本币兑换多少外币","B":"1单位外币兑换多少本币","C":"用黄金表示汇率","D":"用SDR表示汇率"},"answer":"B"},{"id":"west_econ_14_开放条件下的宏观经济_KP01_2","num":"2","stem":"实际汇率的公式是：","options":{"A":"$\\varepsilon = e \\times P/P_f$","B":"$\\varepsilon = e \\times P_f/P$","C":"$\\varepsilon = e + P/P_f$","D":"$\\varepsilon = e \\times P \\times P_f$"},"answer":"A"},{"id":"west_econ_14_开放条件下的宏观经济_KP01_3","num":"3","stem":"已知 $e=7$，$P=100$，$P_f=140$，实际汇率为：","options":{"A":"5","B":"7","C":"9.8","D":"10"},"answer":"A"},{"id":"west_econ_14_开放条件下的宏观经济_KP01_4","num":"4","stem":"本币实际升值会导致：","options":{"A":"出口增加，进口减少","B":"出口减少，进口增加","C":"进出口不变","D":"净出口增加"},"answer":"B"},{"id":"west_econ_14_开放条件下的宏观经济_KP01_5","num":"5","stem":"国际收支平衡表的会计恒等式是：","options":{"A":"经常账户余额=资本账户余额","B":"经常账户余额+资本账户余额=0","C":"经常账户余额=官方储备","D":"资本账户余额=官方储备"},"answer":"B"},{"id":"west_econ_14_开放条件下的宏观经济_KP01_6","num":"6","stem":"下列哪一项属于经常账户？","options":{"A":"直接投资（FDI）","B":"证券投资","C":"货物贸易","D":"外汇储备"},"answer":"C"},{"id":"west_econ_14_开放条件下的宏观经济_KP01_7","num":"7","stem":"香港联系汇率制将港币钉在：","options":{"A":"7.8港币/美元","B":"10港币/美元","C":"8.28港币/美元","D":"与人民币挂钩"},"answer":"A"},{"id":"west_econ_14_开放条件下的宏观经济_KP01_8","num":"8","stem":"中国当前实行的汇率制度是：","options":{"A":"完全固定汇率","B":"完全浮动汇率","C":"以市场供求为基础、参考一篮子货币、有管理的浮动","D":"货币局制度"},"answer":"C"},{"id":"west_econ_14_开放条件下的宏观经济_KP01_9","num":"9","stem":"关于国际收支，下列说法错误的是：","options":{"A":"贸易顺差意味着净出口为正","B":"双顺差会导致外汇储备增加","C":"国际收支平衡表在会计上永远平衡","D":"贸易顺差必然是好事"},"answer":"D"}]},{"id":"KP02","name":"BP曲线","file":"教材笔记/06_西方经济学/14_开放条件下的宏观经济/知识点/KP02_BP曲线.md","questions":[{"id":"west_econ_14_开放条件下的宏观经济_KP02_1","num":"1","stem":"BP曲线表示：","options":{"A":"产品市场均衡时r与Y的组合","B":"货币市场均衡时r与Y的组合","C":"国际收支平衡时r与Y的组合","D":"劳动市场均衡时r与Y的组合"},"answer":"C"},{"id":"west_econ_14_开放条件下的宏观经济_KP02_2","num":"2","stem":"BP曲线向右上方倾斜的原因是：","options":{"A":"Y上升→进口增加→经常账户逆差→需要r上升吸引资本流入","B":"Y上升→出口增加→经常账户顺差→需要r下降","C":"r上升→投资下降→Y下降","D":"r上升→货币需求下降"},"answer":"A"},{"id":"west_econ_14_开放条件下的宏观经济_KP02_3","num":"3","stem":"资本完全流动时，BP曲线的形状是：","options":{"A":"垂直","B":"水平（$r=r_f$）","C":"向右上方倾斜","D":"向右下方倾斜"},"answer":"B"},{"id":"west_econ_14_开放条件下的宏观经济_KP02_4","num":"4","stem":"资本完全不流动时，BP曲线的形状是：","options":{"A":"水平","B":"垂直","C":"向右上倾斜","D":"向右下倾斜"},"answer":"B"},{"id":"west_econ_14_开放条件下的宏观经济_KP02_5","num":"5","stem":"本币贬值会使BP曲线：","options":{"A":"右移","B":"左移","C":"不动","D":"变为水平"},"answer":"A"},{"id":"west_econ_14_开放条件下的宏观经济_KP02_6","num":"6","stem":"已知 $NX = 500 - 0.1Y - 100\\varepsilon$，$CF = 100(r_f - r)$，$r_f=5$，$\\varepsilon=1$。BP曲线方程为：","options":{"A":"$r = 1 + 0.001Y$","B":"$r = 9 - 0.001Y$","C":"$r = 5 + 0.01Y$","D":"$r = 5 - 0.01Y$"},"answer":"A"},{"id":"west_econ_14_开放条件下的宏观经济_KP02_7","num":"7","stem":"BP曲线左上方的点表示：","options":{"A":"国际收支顺差","B":"国际收支逆差","C":"国际收支平衡","D":"无法判断"},"answer":"A"},{"id":"west_econ_14_开放条件下的宏观经济_KP02_8","num":"8","stem":"外国收入增加会使BP曲线：","options":{"A":"右移","B":"左移","C":"不动","D":"变为垂直"},"answer":"A"},{"id":"west_econ_14_开放条件下的宏观经济_KP02_9","num":"9","stem":"关于BP曲线，下列说法错误的是：","options":{"A":"BP曲线向右上倾斜（资本不完全流动时）","B":"资本完全流动时BP水平","C":"BP曲线和LM曲线都向右上倾斜，机制相同","D":"BP曲线位置受汇率、外国收入影响"},"answer":"C"}]},{"id":"KP03","name":"蒙代尔-弗莱明模型","file":"教材笔记/06_西方经济学/14_开放条件下的宏观经济/知识点/KP03_蒙代尔弗莱明模型.md","questions":[{"id":"west_econ_14_开放条件下的宏观经济_KP03_1","num":"1","stem":"蒙代尔-弗莱明模型的关键假设不包括：","options":{"A":"资本完全流动","B":"小国经济","C":"价格灵活调整","D":"汇率制度固定或浮动"},"answer":"C"},{"id":"west_econ_14_开放条件下的宏观经济_KP03_2","num":"2","stem":"固定汇率制下，财政政策：","options":{"A":"有效","B":"无效","C":"不确定","D":"只影响汇率不影响产出"},"answer":"A"},{"id":"west_econ_14_开放条件下的宏观经济_KP03_3","num":"3","stem":"固定汇率制下，货币政策：","options":{"A":"有效","B":"无效","C":"短期有效长期无效","D":"只影响汇率"},"answer":"B"},{"id":"west_econ_14_开放条件下的宏观经济_KP03_4","num":"4","stem":"浮动汇率制下，财政政策：","options":{"A":"有效","B":"无效（挤出净出口）","C":"只影响汇率","D":"短期有效"},"answer":"B"},{"id":"west_econ_14_开放条件下的宏观经济_KP03_5","num":"5","stem":"浮动汇率制下，货币政策：","options":{"A":"有效（通过本币贬值增加净出口）","B":"无效","C":"只影响汇率","D":"只影响利率"},"answer":"A"},{"id":"west_econ_14_开放条件下的宏观经济_KP03_6","num":"6","stem":"固定汇率制下，央行扩张货币的最终结果是：","options":{"A":"Y增加","B":"Y不变，外汇储备减少","C":"Y不变，外汇储备增加","D":"汇率贬值"},"answer":"B"},{"id":"west_econ_14_开放条件下的宏观经济_KP03_7","num":"7","stem":"浮动汇率制下，扩张财政政策导致本币：","options":{"A":"升值","B":"贬值","C":"不变","D":"先升后贬"},"answer":"A"},{"id":"west_econ_14_开放条件下的宏观经济_KP03_8","num":"8","stem":"香港联系汇率制下，香港货币政策：","options":{"A":"独立，跟随香港经济周期","B":"不独立，跟随美联储","C":"跟随中国人民银行","D":"由香港金管局自主决定"},"answer":"B"},{"id":"west_econ_14_开放条件下的宏观经济_KP03_9","num":"9","stem":"欧元区各国在货币政策上：","options":{"A":"各自独立决定利率","B":"由欧洲央行统一决定，各国失去独立货币政策","C":"由德国央行决定","D":"由IMF决定"},"answer":"B"},{"id":"west_econ_14_开放条件下的宏观经济_KP03_10","num":"10","stem":"蒙代尔-弗莱明模型的政策组合结论是：","options":{"A":"固定汇率选财政，浮动汇率选货币","B":"固定汇率选货币，浮动汇率选财政","C":"任何汇率制度下财政都有效","D":"任何汇率制度下货币都有效"},"answer":"A"}]},{"id":"KP04","name":"三元悖论","file":"教材笔记/06_西方经济学/14_开放条件下的宏观经济/知识点/KP04_三元悖论.md","questions":[{"id":"west_econ_14_开放条件下的宏观经济_KP04_1","num":"1","stem":"三元悖论的三个目标不包括：","options":{"A":"货币政策独立性","B":"固定汇率","C":"资本自由流动","D":"财政政策独立性"},"answer":"D"},{"id":"west_econ_14_开放条件下的宏观经济_KP04_2","num":"2","stem":"香港选择的组合是：","options":{"A":"固定汇率+资本自由流动，放弃货币独立","B":"货币独立+资本自由流动，放弃固定汇率","C":"固定汇率+货币独立，放弃资本自由流动","D":"三者都要"},"answer":"A"},{"id":"west_econ_14_开放条件下的宏观经济_KP04_3","num":"3","stem":"美国选择的组合是：","options":{"A":"固定汇率+资本自由流动","B":"货币独立+资本自由流动，浮动汇率","C":"固定汇率+货币独立，资本管制","D":"三者都要"},"answer":"B"},{"id":"west_econ_14_开放条件下的宏观经济_KP04_4","num":"4","stem":"中国目前的组合是：","options":{"A":"固定汇率+资本自由流动","B":"货币独立+资本自由流动","C":"管理浮动汇率+货币独立+资本账户管制","D":"三者都要"},"answer":"C"},{"id":"west_econ_14_开放条件下的宏观经济_KP04_5","num":"5","stem":"三元悖论的提出者是：","options":{"A":"凯恩斯","B":"蒙代尔（克鲁格曼推广）","C":"弗里德曼","D":"萨缪尔森"},"answer":"B"},{"id":"west_econ_14_开放条件下的宏观经济_KP04_6","num":"6","stem":"一个国家同时想要固定汇率、资本自由流动、独立货币政策，会发生：","options":{"A":"三者都能实现","B":"必然放弃其中一个","C":"只有大国能实现","D":"只有小国能实现"},"answer":"B"},{"id":"west_econ_14_开放条件下的宏观经济_KP04_7","num":"7","stem":"1997年亚洲金融危机中，泰国失败的原因是：","options":{"A":"想同时实现固定汇率、资本自由流动、独立货币政策","B":"汇率完全浮动","C":"资本完全管制","D":"没有外汇储备"},"answer":"A"},{"id":"west_econ_14_开放条件下的宏观经济_KP04_8","num":"8","stem":"中国推进资本账户开放，长期方向是：","options":{"A":"放弃货币独立","B":"汇率更灵活浮动，保留货币独立","C":"回到固定汇率","D":"取消外汇储备"},"answer":"B"},{"id":"west_econ_14_开放条件下的宏观经济_KP04_9","num":"9","stem":"2022—2024年美联储加息周期中，中国得以维持降息，主要依靠：","options":{"A":"完全固定汇率","B":"资本账户管制缓冲","C":"资本完全自由流动","D":"大量抛售美元"},"answer":"B"},{"id":"west_econ_14_开放条件下的宏观经济_KP04_10","num":"10","stem":"关于三元悖论，下列说法错误的是：","options":{"A":"三个目标最多同时实现两个","B":"中国当前是第三组合","C":"欧元区各国保留独立货币政策","D":"香港放弃了独立货币政策"},"answer":"C"}]},{"id":"KP99","name":"曲线移动专项","file":"","questions":[{"id":"west_econ_14_开放条件下的宏观经济_KP99_1","num":"1","stem":"（曲线移动·判断题）本币实际升值（出口变贵、进口变便宜），BP 曲线如何移动？（　）","options":{"A":"BP 曲线左移（同一 Y 下需要更高利率才能平衡国际收支）","B":"BP 曲线右移","C":"BP 曲线不动","D":"BP 曲线变水平"},"answer":"A"},{"id":"west_econ_14_开放条件下的宏观经济_KP99_2","num":"2","stem":"（曲线移动·判断）国外利率 rf 大幅上升（如美联储暴力加息），在资本可流动时本国 BP 曲线如何？（　）","options":{"A":"BP 线上移（本国须提高利率才能留住资本）","B":"BP 线下移","C":"BP 线不动","D":"BP 线变垂直"},"answer":"A"},{"id":"west_econ_14_开放条件下的宏观经济_KP99_3","num":"3","stem":"（曲线移动·分析）本国加征关税、限制进口（贸易保护），BP 曲线如何移？（　）","options":{"A":"BP 曲线右移（净出口改善，同一 Y 下国际收支更易平衡）","B":"BP 左移","C":"不动","D":"BP 变垂直"},"answer":"A"}]}]};
